quests[45479] = { id = 45479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kosumoth the Hungering" }
quests[45482] = { id = 45482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane: Fate of the Tideskorn", description = "A scout from Stormheim arrived yesterday with a significant discovery - these ancient scrolls. Within they contain a Valkyra prophecy of a new vrykul ruler - one who could turn the Tideskorn against the Legion.\n\nIt complicates matters that this vrykul may in fact be Skovald's heir.\n\nTake the scrolls, find the heir, and bring her to the Valkyra. I think the outcasts they refer to are the vrykul of Jandvik, so that would be a good place to start.", completion = "Yes, outsider? What business do you have here?", objectives = "Search Jandvik for the vrykul mentioned in the scrolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
