quests[45485] = { id = 45485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aodh Witherpetal" }
quests[45486] = { id = 45486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reluctant Queen", description = "Wait, how is it you know about my parentage? Be careful what you say around here, there are those who would hunt me down if they knew my bloodline.\n\nI don't know who you are, nor do I believe I'm part of any prophecy. However, if you seek to undo the damage my father has wrought on the Tideskorn, then I feel obliged to assist you.\n\nMeet me in Valdisdall, {class}. From there we can make our way to Skold-Ashil and request an audience with Eyir. Perhaps she can shed some light on this prophecy.", completion = "I thank you for bringing Sigryn to me, outsider. She truly is the future of our people.\n\nThough you have already done so much, I would ask another favor of you. Please accompany Sigryn in her challenges. She has grown to trust you, and will need guidance through the trials she must face.", objectives = "Bring Sigryn before Eyir in Skold-Ashil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
