quests[45584] = { id = 45584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadful Gladiator's Dragonhide Armor" }
quests[45585] = { id = 45585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadful Gladiator's Dreadplate Armor" }
quests[45586] = { id = 45586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shield Amplification", description = "It will not hurt to reinforce the Nightborne Soulstone's shield just a bit more, and to do that we must infuse it with energy. \n\nRyanna has assured me that fel essence will work beautifully for our needs. Yes - this method IS rather distasteful. However as the sin'dorei well know, desperate times call for desperate measures.\n\nIt is as simple as this: we have an urgent need for magical energy, and our enemies possess it in abundance. \n\nDo what must be done.", completion = "Good. The Soulstone's shields should be sufficiently strengthened now.", objectives = "Use the Nightborne Soulstone on defeated Felborne within the Weeping Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45587] = { id = 45587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Feltotem Menace", description = "If I had known Tugar was alive and behind this I would've alerted you sooner! He is a hateful creature, and an easy recruit to the Legion's cause.\n\nIf he is truly successful with his fel experiments we need to stop him now. He is taunting us from up there. Let's go!", completion = "That was powerful fel magic. If it is true, if he is raising an army of such beasts... Thunder Totem is in peril!", objectives = "Find and deal with Tugar Bloodtotem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45593] = { id = 45593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadful Gladiator's Felweave Armor" }
