quests[45613] = { id = 45613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grievous Gladiator's Silk Armor" }
quests[45614] = { id = 45614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lady Remor'za", description = "Our allies reported a coven of extremely powerful Felborne abjurers occupying the Weeping Terrace. \n\nTheir leader, Lady Remor'za, and her followers are specialists in ancient nightborne magic and can become nearly invincible to attacks. \n\nHowever, as mages, we should be able to defeat them using Spellsteal. Let us show them the power of the Tirisgarde!", completion = "The Felborne will respect the Tirisgarde now, do you not agree?", objectives = "Kill Lady Remor'za.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45615] = { id = 45615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finders Keepers", description = "Would you look at this place? It's a mess! Everywhere you look there's just pile after pile of arcane dust!\n\n<Akazamzarak smiles broadly.>\n\nThese poor saps don't realize what that stuff's worth!\n\nI tell ya what, if you help me summon up some brooms to collect this powdered gold, I'll split the profits with you 80/20.", progress = "Say, how's that dust coming along?", completion = "Now that's what I'm talking about! You know what they say - where there's mages, there's dust!", objectives = "Sweep up 8 piles of Arcane Dust in the Hall of the Guardian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45616] = { id = 45616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grievous Gladiator's Dreadplate Armor" }
quests[45617] = { id = 45617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grievous Gladiator's Dragonhide Armor" }
