quests[45619] = { id = 45619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grievous Gladiator's Ironskin Armor" }
quests[45620] = { id = 45620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grievous Gladiator's Leather Armor" }
quests[45621] = { id = 45621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grievous Gladiator's Plate Armor" }
quests[45622] = { id = 45622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grievous Gladiator's Ringmail Armor" }
quests[45623] = { id = 45623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grievous Gladiator's Satin Armor" }
quests[45624] = { id = 45624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grievous Gladiator's Scaled Armor" }
quests[45625] = { id = 45625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grievous Gladiator's Silk Armor" }
quests[45626] = { id = 45626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Set You Up the Bomb!" }
quests[45627] = { id = 45627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feltotem's Fall", description = "Our Highmountain contact, Navarrogg, reports that Tugar Bloodtotem has finally resurfaced.\n\nHe's sent a message crystal along with some instructions for me.\n\nI can teleport you to Navarrogg and he will take you to Tugar's location, but there is one problem.\n\nNavarrogg requires additional magical power to fend off Tugar's fel magicks. You will need some Nethershards before you go.", completion = "Thunder Totem and countless lives are saved. One more crisis down in this war against the Legion.", objectives = "Defeat Tugar Bloodtotem. Speak with War Councilor Victoria, she will teleport you to Navarrogg to begin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45628] = { id = 45628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Time, Leave a Trail", description = "Are you ready, {class}t? I will walk you through every step of the plan. You'll be perfectly safe! First thing's first: You see that rappel point behind me? That's your way down into the cave. Good luck!", completion = "That couldn't have gone better if I had done it myself. Good work, Shadowblade.", objectives = "Rappel down into the cave, then follow Tess's instructions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45629] = { id = 45629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Time, Leave a Trail", description = "Here goes nothing, {class}t. If anybody can pull this off, you can! ...Probably. Just use the rappel point behind me to get into the cave.\n\nWhat? Don't make that face. I'll give you more instructions once you're in the cave.", completion = "That couldn't have gone better if I had done it myself. Good work, Shadowblade.", objectives = "Rappel down into the cave, then follow Lilian's instructions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45630] = { id = 45630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Servant to No One", description = "I like workin' with ya, {name}. How's about we keep this gold train a-rollin'?\n\nArchmage Khadgar spends an inordinate amount of time sending his servants off to do who knows what. What if an enterprising duo such as ourselves found a cheaper alternative?\n\n<Akazamzarak hands you a small crystal.>\n\nThis bad boy will form a servant right out of thin air - and a few pounds of the dust you swept up.\n\nWhy not take it into town and try her out? See for yourself!", progress = "Good stuff, am I right?", completion = "You make a pretty good business partner, bud! I'll see what I can do to get ol' Khadgar on board with these new servants. \n\nI tell ya I'm gonna make a fortune!\n\nOh, don't think I forgot you. I've got somethin' special in mind for ya!", objectives = "Test Akazamzarak's Servants on 5 people in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45631] = { id = 45631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avocation of Antonidas", description = "Archmage, I've found something you may be interested in. An old journal of the late Archmage, Antonidas. In it, he speaks of a project he was working on that I think we may be able to finish.\n\nIt was a sort of flying disc that could attune itself to the rider's magical attunement.\n\nBut I need your help tracking down the pieces. From what I could gather, he gave them to trusted friends and allies through the years. Perhaps you could persuade them to give us the pieces.", objectives = "Recover the three discs of Antonidas' unfinished project and return them to Kalec in your order hall. Speak to Archmage John Nicholas in Northrend, at the Purple Parlor about the Tri-Disc of the Arcane. Speak with Khadgar about the Tri-Disc of Fire. And speak with Archmage Cedric near the Dalaran Crater about the Tri-Disc of Frost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45632] = { id = 45632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing in Action: Eitrigg", description = "Are you familiar with Eitrigg? He is the worthy orc warrior who was leading our forces against the Felrage naga nearby.\n\nUnfortunately the naga captured many of our soldiers during a recent skirmish. Eitrigg went after them and has not returned. I fear something terrible has happened to him.\n\nPlease try to find him!", completion = "The filthy naga ambushed me. I will not fail again.", objectives = "Find Eitrigg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45633] = { id = 45633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Felrage", description = "I do not like to see naga aligned with the Burning Legion. That is something new and cannot be ignored.\n\nThe naga warlord, Kaz'jatar, and his skrog toady, Felbeard, are responsible for the Felrage's attacks on our forces.\n\nWe must teach them that it does not pay to consort with demons!", progress = "Warlord Kaz'jatarand Felbeard must pay for their crimes against us!", completion = "With their leaders defeated, the Felrage naga will not be preying on our warriors again. Still, we should keep an eye on them in the future.", objectives = "Kill Warlord Kaz'jatar and Felbeard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45634] = { id = 45634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kvaldir on Call", description = "You empowered Helya's Horn in Helheim, and now is the time to use it. I have located three Legion portals we should eliminate. \n\nSeek out the vrykul shipwreck on Felrage Strand. Call the kvaldir and have them do what they do best: destroy!", progress = "Did the kvaldir answer your call, {name}?", completion = "Well done, {name}. The kvaldir will be useful tools in the battles to come.", objectives = "Blow Helya's Horn and direct the kvaldir to destroy the three Legion portals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45637] = { id = 45637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandworm Meat", progress = "Gettin' de colossi to wake up takes a whole heap of meat. Lucky for you, Silithus is crawling with sandworms, and the colossi don't seem to mind da taste.", completion = "Many thanks, friend.\n\nFor the Horde!" }
quests[45638] = { id = 45638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crunchy Spider Legs", progress = "We need meat - any kind of meat - to feed de colossi. And there's no cheaper meat than spider meat. You can find plenty of it out in Outland.", completion = "With your help, the Horde may win dis ting." }
quests[45639] = { id = 45639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chilled Meat", progress = "De beasts of Northrend are big, heavy, and full of meat. Go find sometin' we can feed to the colossi.", completion = "This will work just fine. De Horde thanks you, bruddah." }
quests[45640] = { id = 45640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crocolisk Tails", progress = "De crocolisks of Uldum are known for bein' bigger than all the rest. When you need lots of meat in a hurry, they're always a good option.", completion = "Keep the meat deliveries comin', {name}. We need all we can get." }
quests[45641] = { id = 45641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raw Tiger Steaks", progress = "Down south, in Pandaria, the tigers grow fat hunting smaller creatures. Bring me some of their meat.", completion = "Excellent hunting, {class}." }
quests[45642] = { id = 45642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raw Clefthoof Meat", progress = "Gorchuk tells me that the old {race} clans of Draenor used to prize the clefthoof for its size - one kill could feed a village for a night.", completion = "Look at that mountain of meat. You done de Horde proud, {name}." }
quests[45643] = { id = 45643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lean Shanks", progress = "We need meat, and lots of it. You look pretty tough - maybe you could go slay some beasts in de Broken Isles.", completion = "You make your Warchief proud. For da Horde!" }
quests[45644] = { id = 45644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh Doloria, My Sweet Doloria", description = "What ho! We are quite the dashing pair of adventurers, aren't we?\n\nNow that we have secured my belongings, a new path unfolds before us. I did not journey here simply to thwart the demon invasion, no! I came here in search of my beloved, my loved, Doloria. Whilst resting between slaying of dragons, I had a dream, nay, a vision. It told me Doloria had been kidnapped and taken to a floating city in the sky!\n\nIt must be Dalaran. Quickly, squire! Mount up and meet me at Dalaran's famous inn. Make haste!", completion = "Blast, I didn't think he would find me again so fast.", objectives = "Seek out Doloria in the Legerdermain Lounge in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45645] = { id = 45645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fool's Errand", description = "Oh yea sure, I'm, um, held here against my, you know, will, or something.\n\nLook bud, between you and me old Max here has no chance, but his heart is in the right place. I keep trying to run away and hide but he keeps finding me! I just don't have it in me to upset him with the truth.\n\nI've got an idea. Why don't you go kill some of those really big two headed \"Hill Bandits\" for me. Let's say they stole some jewelery from me, and you can use it to buy my freedom.\n\nTake your time, don't get hurt. Much.", progress = "Kill \"Hill Bandits\" to find Dolorias stolen \"Jewelry\" and buy her \"release\"", completion = "<Doloria gives you a sly wink from behind her mask>\n\nUh, no, haven't seen her for a few days, not sure who you're talking about.", objectives = "Kill \"Hill Bandits\" to find Doloria's stolen \"Jewelry\" and buy her \"release\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45647] = { id = 45647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Search and Rescue", description = "I will make these naga pay for their audacity. \n\nThey and their skrog lackeys captured our warriors while we were fighting the Legion. They have no honor!\n\nWe must rescue our fallen soldiers before they are sold as slaves, or worse...", progress = "Have we found them all?", completion = "Our soliders will be back in action soon, and the Felrage naga will think twice before messing with us again!", objectives = "Rescue 8 squads of Captured Warriors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45648] = { id = 45648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing in Action: Lord Darius Crowley", description = "Are you familiar with Lord Darius Crowley? He is the worthy Gilnean warrior who was leading our forces against the Felrage naga nearby. \n\nUnfortunately the naga captured many of our soldiers during a recent skirmish. Lord Darius went after them and has not returned. I fear something terrible has happened to him.\n\nPlease try to find him!", completion = "Thanks. I was ambushed by a dozen naga and skrog! At least I took quite a few down before they overwhelmed me...", objectives = "Search for Lord Darius Crowley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45649] = { id = 45649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Search and Rescue", description = "I will make these naga pay for their audacity. \n\nThey and their skrog lackeys captured our warriors while we were fighting the Legion. They have no honor!\n\nWe must rescue our fallen soldiers before they are sold as slaves, or worse...", progress = "Have we found them all?", completion = "Our soliders will be back in action soon, and the Felrage naga will think twice before messing with us again!", objectives = "Rescue 8 squads of captured warriors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45650] = { id = 45650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Felrage", description = "I am very concerned to discover naga aligned with the Burning Legion. That is something new and cannot be ignored.\n\nThe naga warlord, Kaz'jatar, and his skrog toady, Felbeard, are responsible for the Felrage's attacks on our forces.\n\nWe must teach them that it does not pay to consort with demons!", progress = "Warlord Kaz'jatarand Felbeard must pay for their crimes against us!", completion = "With their leaders defeated, the Felrage naga won't be launching any more raids for awhile! Still, we should keep an eye on them in the future.", objectives = "Kill Warlord Kaz'jatar and Felbeard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45651] = { id = 45651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Ahn'Qiraj: Ossirian" }
quests[45652] = { id = 45652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A \"Humble\" Request", description = "{class}t, we've received a... visitor. She orders entry, but the guards will not let her pass without approval.\n\nPlease head up to the overlook as soon as you are able.", progress = "Our \"guest\" is waiting for you. You may want to hurry.", completion = "You're in charge here?", objectives = "Meet your visitor at Storm's Eye Overlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45653] = { id = 45653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill it with Fire!" }
