quests[45682] = { id = 45682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looted Rogue Vault" }
quests[45694] = { id = 45694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arachnicide" }
quests[45706] = { id = 45706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of Thousands", description = "I know I am not well liked here, and my Grimtotem and I were not invited to join you and your shaman here. However, I come to you with a proposition.\n\nThe Legion is attacking my home. I've lost possession of some things that are... dear to me, and I have nowhere else to turn to. It pains me to ask... but I request your aid. If you help, I offer my people in service against the Legion.", completion = "Let's not keep my tribe waiting.", objectives = "Take Magatha's portal and meet her in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45723] = { id = 45723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crone's Wrath", description = "These demons come into my home, take my things, and capture my people? They will see my wrath. Destroy them, child. Surely you are capable of at least that.", completion = "Fel blood has never been sweeter.", objectives = "Defeat 15 demons on Darkcloud Pinnacle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45724] = { id = 45724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snakes and Stones", description = "When the demons attacked, they captured two very powerful possessions of mine: my companion Arikara and the Doomstone.\n\nWhile death matters not to Arikara, the Legion surely has ulterior plans for him. And the Doomstone... such an artifact of power belongs in my hands, not theirs. We must split up to find them.\n\nFor the world's sake, do be careful. I don't need you clumsily destroying everything.", progress = "Greetings, Farseer. What have you found?", completion = "I reclaimed Arikara. Did you find the Doomstone?", objectives = "Find either the Doomstone or Arikara on Darkcloud Pinnacle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45725] = { id = 45725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Chains", description = "The Legion shall not make fools of the Grimtotem. Free my people, and we will grace you with our aid in the coming battle.", completion = "The Legion cannot break the Grimtotem.", objectives = "Free 8 Captured Grimtotem from Prison Cages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45726] = { id = 45726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tainted Marsh", description = "I wasn't able to scout inside the village yet, however, there are more dangerous experiments going on to the south. They were befouling the unquiet spirits in the marshlands with more fel magic!\n\nI will rework this fel totem to draw out the fel energies they infused in those spirits.\n\nPlease, cure what spirits you can, perhaps it will even give them some peace.\n\nIf you want, I can even send you there!", progress = "I'm tired of these monsters abusing everything around them!", completion = "You've done those souls a great favor. I hope they find peace.\n\nLet's cut off these experiments at the source now.", objectives = "Drain the fel energies from the spirits of the Blind Marshlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45727] = { id = 45727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uniting the Isles", description = "There are a great number of factions here on the Broken Isles. We must unite them if we want to stand a chance against the Legion. Prove your worth to them and report back to me.", completion = "Excellent work, {name}. We still have a long road ahead of us to rid this world of the Legion, but this brings us one step closer.", objectives = "Speak to Archmage Khadgar in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45728] = { id = 45728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion Assault: Thunder Totem" }
quests[45729] = { id = 45729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandworm Meat", progress = "Convincing the giant colossi of Silithus to wake up requires a whole heap of meat. Lucky for you, Silithus is crawling with sandworms, and the colossi don't seem to mind the taste too much!", completion = "Many thanks, friend.\n\nFor the Alliance!" }
quests[45730] = { id = 45730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crunchy Spider Legs", progress = "We need meat - any kind of meat - to feed the colossi... and there's no cheaper meat than spider meat. You can find plenty of it out in Outland.", completion = "With your help, the Alliance may win this thing." }
quests[45731] = { id = 45731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chilled Meat", progress = "The beasts of Northrend are big, heavy, and full of meat. Go find something we can feed to the colossi.", completion = "This will work just fine. The Alliance thanks you." }
quests[45732] = { id = 45732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crocolisk Tails", progress = "The crocolisks of Uldum are known for being bigger than all the rest. When you need lots of meat in a hurry, they're always a good option.", completion = "Keep the meat deliveries coming, {name}. We need all we can get." }
quests[45733] = { id = 45733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raw Tiger Steaks", progress = "Down south, in Pandaria, the tigers grow fat hunting smaller creatures. Bring me some of their meat.", completion = "Excellent hunting, {class}." }
quests[45734] = { id = 45734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raw Clefthoof Meat", progress = "I remember reading that the old orc clans of Draenor used to prize the clefthoof for its size - one kill could feed a village for a night.", completion = "Look at that mountain of meat. You have done the Alliance proud, {name}." }
quests[45735] = { id = 45735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lean Shanks", progress = "We need meat, and lots of it. You look pretty tough - maybe you could go slay some beasts in the Broken Isles.", completion = "You make your King proud. For the Alliance!" }
quests[45736] = { id = 45736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Ahn'Qiraj: Ossirian" }
