quests[45743] = { id = 45743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Judgment of Odyn" }
quests[45744] = { id = 45744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fall of the Felskorn" }
quests[45745] = { id = 45745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion 110 PvP" }
quests[45746] = { id = 45746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvation", description = "The valley is swarming with fel-corrupted creatures who are beyond saving, yet there still may be some that could use our help.\n\nTake this manaroot salve and apply it to any animals you see. If the fel magic hasn't taken hold, the salve might be able to mend their wounds.", objectives = "Use the Manaroot Salve on fel-infected animals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45747] = { id = 45747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cinder of Cynders", description = "The cinder seethes with the hatred that its former owner held for you.", progress = "Have you brought me trophies of war?", completion = "Well done, {race}. For the Horde!", objectives = "Bring the Cinder of Cynders to Warlord Gorchuk in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45748] = { id = 45748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pearl of Fathoms", description = "The pearl is immaculately smooth, and surprisingly dense.", progress = "I'm not in the market for jewelry, {class}...", completion = "Oh, I see. This is a trophy of battle.\n\nWe will add it to the many treasures you and your fellow adventurers have brought. For the Horde!", objectives = "Bring the Pearl of Fathoms to Warlord Gorchuk in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45749] = { id = 45749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salt of Shards", description = "The Abyssal Lord left behind a small pile of faintly-iridescent sand.", progress = "What do you have there? That isn't Silithyst, is it?", completion = "Ahh, the trophy of an epic battle. Well fought, {class}!", objectives = "Bring the Salt of Shards to Warlord Gorchuk in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45750] = { id = 45750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Song of Zephyrs", description = "A swirling essence coalesces at the feet of the Duke.", progress = "You wrote me a song? How thoughtful.", completion = "Ah, I see, it is a hard-earned reward from one of your many battles. Well done, {class}!", objectives = "Bring the Song of Zephyrs to Warlord Gorchuk in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45751] = { id = 45751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coreforged Sigil of Skaldrenox", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was forged in flame.", progress = "What news from the battlefield, {race}?", completion = "This is an impressive find indeed. The Abyssal High Council do not part with their sigils easily.", objectives = "Bring the Coreforged Sigil of Skaldrenox to Warlord Gorchuk in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45752] = { id = 45752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glimmering Sigil of Whirlaxis", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was carved with biting winds.", progress = "You've returned from battle, {race}. Any trophies to share?", completion = "To wrest a sigil from one of the Abyssal High Council is a feat worthy of praise. For the Horde!", objectives = "Bring the Glimmering Sigil of Whirlaxis to Warlord Gorchuk in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45753] = { id = 45753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diamondine Sigil of Kazum", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was carved from stone, then fused into a faultless diamond.", progress = "A diamond ring? Why... why are you bringing this to me?", completion = "Ah, a sigil. From the Abyssal High Council, no less!\n\n<Warlord Gorchuk wipes a bead of sweat from his brow.>\n\nI... I had assumed that it was... that you were... oh, never mind.\n\nFor the Horde!", objectives = "Bring the Diamondine Sigil of Kazum to Warlord Gorchuk in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45754] = { id = 45754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tidal Sigil of Skwol", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was crafted from coral and smoothed by the tides.", progress = "What have we here?", completion = "A sigil from the Abyssal High Council? You've outdone yourself today, {race}.\n\nFor the Horde!", objectives = "Bring the Tidal Sigil of Skwol to Warlord Gorchuk in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45755] = { id = 45755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cinder of Cynders", description = "The cinder seethes with the hatred that its former owner held for you.", progress = "Have you brought me trophies of war?", completion = "Well done, {race}. For the Alliance!", objectives = "Bring the Cinder of Cynders to Field Marshal Snowfall in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45756] = { id = 45756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pearl of Fathoms", description = "The pearl is immaculately smooth, and surprisingly dense.", progress = "I'm not in the market for jewelry, {class}...", completion = "Oh, I see. This is a trophy of battle.\n\nWe will add it to the many treasures you and your fellow adventurers have brought. For the Alliance!", objectives = "Bring the Pearl of Fathoms to Field Marshal Snowfall in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45757] = { id = 45757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salt of Shards", description = "The Abyssal Lord left behind a small pile of faintly-iridescent sand.", progress = "What do you have there? That isn't Silithyst, is it?", completion = "Ahh, the trophy of an epic battle. Well fought, {class}!", objectives = "Bring the Salt of Shards to Field Marshal Snowfall in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45758] = { id = 45758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Song of Zephyrs", description = "A swirling essence coalesces at the feet of the Duke.", progress = "You wrote me a song? How thoughtful.", completion = "Ah, I see, it is a hard-earned reward from one of your many battles. Well done, {class}!", objectives = "Bring the Song of Zephyrs to Field Marshal Snowfall in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45759] = { id = 45759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coreforged Sigil of Skaldrenox", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was forged in flame.", progress = "What news from the battlefield, {race}?", completion = "This is an impressive find indeed. The Abyssal High Council do not part with their sigils easily.", objectives = "Bring the Coreforged Sigil of Skaldrenox to Field Marshal Snowfall in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45760] = { id = 45760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glimmering Sigil of Whirlaxis", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was carved with biting winds.", progress = "You've returned from battle, {race}. Any trophies to share?", completion = "To wrest a sigil from one of the Abyssal High Council is a feat worthy of praise. For the Alliance!", objectives = "Bring the Glimmering Sigil of Whirlaxis to Field Marshal Snowfall in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45761] = { id = 45761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diamondine Sigil of Kazum", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was carved from stone, then fused into a faultless diamond.", progress = "A diamond ring? Why... why are you bringing this to me?", completion = "Ah, a sigil. From the Abyssal High Council, no less!\n\n<Field Marshal Snowfall wipes a bead of sweat from his brow.>\n\nI... I had assumed that it was... that you were... oh, never mind.\n\nFor the Alliance!", objectives = "Bring the Diamondine Sigil of Kazum to Field Marshal Snowfall in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45762] = { id = 45762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tidal Sigil of Skwol", description = "The sigils of the Abyssal High Council are crafted from the distilled essence of the element of their holder. This sigil was crafted from coral and smoothed by the tides.", progress = "What have we here?", completion = "A sigil from the Abyssal High Council? You've outdone yourself today, {race}.\n\nFor the Alliance!", objectives = "Bring the Tidal Sigil of Skwol to Field Marshal Snowfall in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45763] = { id = 45763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonic Disruption", description = "While scouting on the Broken Shore, we have stumbled upon something quite unsettling.\n\nThe Legion is attempting to harness the powers of Azeroth's elements. What is more, they are succeeding.\n\nWe must stop them at all costs. I can open a portal for you to meet Therazane at the Garrison of the Fel. She will update you on the situation.", completion = "The Legion is forcing Azeroth to bend to its will. We cannot allow this any longer!", objectives = "Speak to Farseer Nobundo to go to the Broken Shore, then meet Therazane at the Garrison of the Fel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45764] = { id = 45764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring Equilibrium", description = "Kor'vass sent a report on the status of the Fel Hammer. It suffered major damage, and is now even uglier than before if that'ss even possible...\n\nIt hass also begun listing to one side - rather comically, I might add. For some reason, Kor'vass doesn't find this nearly as entertaining as she should.\n\nAnyway, there are stabilizer crystalss around the Tomb of Sargerass she could use for repairss.\n\nSay the word and I will direct a squadron of illidari batriderss to accompany you. I'd come too, but...", progress = "Have you secured the materialss for repairing the Fel Hammer, {name}?", completion = "It'ss a shame the batriderss didn't make it. Even more reason to blast the hell out of the Legion as soon as the Fel Hammer'ss weaponss core iss operational again.", objectives = "Obtain 3 Stabilizing Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45765] = { id = 45765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brothers and Sisters", description = "Your people were trying to stop the Legion before you arrived, but flesh is weak and they accumulated too many wounds. Without your aid, they will surely perish at the hands of the demons. Go, help them.", progress = "Rock may chip, but it does not bleed as flesh does.", completion = "I provided cover as the weaker of your people retreated. They will return to the Maelstrom safely.", objectives = "Heal 8 Injured Shaman  in Garrison of the Fel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45766] = { id = 45766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Albino Elderhorn" }
quests[45767] = { id = 45767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Cores", description = "The eredar here are abusing the power of all of Azeroth's elements, forcing them to their command using their fel magics. They succeed to do this through curiosities the Legion has developed, cores of power that correspond to each element.\n\nDo not allow the Legion to continue abusing our world. Kill them and take the sources of their power.", progress = "Nobody should force the elements to bend to their will. Show the Legion that their understanding is flawed.", completion = "It seems the Doomstone is pulsating with energy.", objectives = "Collect 3 Fire Power Cores, 3 Water Power Cores, 3 Earth Power Cores, and 3 Air Power Cores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45769] = { id = 45769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conflagration", description = "That fiend! Up on the hill, a demon who calls himself \"The Flameripper\" is using the power of my realm. Your shaman die as he draws power from the Firelands, mixing the fire of our world with the unholy flame of his.\n\nHe is extremely powerful, Farseer. You must take him down, whatever the cost!", completion = "Ah, you've awoken. I have heard tale of what happened.", objectives = "Kill Barastagax the Flameripper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45770] = { id = 45770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stirring in the Shadows", description = "We must now purify the barding by both material and immaterial means. For the material, we need to travel to Stratholme.\n\nWhen it thrived, before the plague, it produced holy water capable of cleansing even the darkest of magics. There still may be caches of it lying untouched there that we can use.\n\nThen it's just a matter of imbuing enough holy power into the barding to make sure it overcomes the will of Rivendare's mount, Shadowmane.\n\nTravel to the service gate of Stratholme when you're ready.", progress = "Your mount is within our reach, Highlord. I only pray Stratholme still has an ample supply of holy water.", completion = "That was quite the encounter, wouldn't you say Highlord {name}? Reminds me of my glory days.\n\nNevertheless we'll be keeping a more watchful eye on Stratholme from now on. But that's not important right now.\n\nWe should move on to the ceremony and have you claim your prize!", objectives = "Meetup with Lord Grayson Shadowbreaker in Stratholme. Once inside, locate the remains of Lord Rivendare and his mount and perform the ritual to claim it as your own.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45771] = { id = 45771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Time for Everything", description = "Our order is recovering thanks to your quick actions, Grandmaster. \n\nThere is just one more monk we need to attend to before it is too late!", completion = "Grandmaster {name}, these old bones grow weary. Our future depends on you to continue the fight against the Legion.\n\nSo long as you remain a beacon of light in the darkness, hope remains!", objectives = "Give the Curative Brew to Iron-Body Ponshu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45773] = { id = 45773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.2 Class Hall - Maximillian of Northshire - Aqcuisition - Track Mail Sent" }
quests[45776] = { id = 45776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keys are a Crutch" }
quests[45785] = { id = 45785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Scarab", description = "The Call of the Scarab event is occurring today. Speak with your faction's leader near the Gates of Ahn'Qiraj.", completion = "And who are you? {name}?\n\nAhh... yes, I believe I've heard mention of you before. Welcome to Silithus, {name}.\n\nToday, we celebrate our heritage as sons of Kalimdor. Furthermore, we prove that the Horde will always grind those puny Alliance into the ground.\n\nAre you with me?", objectives = "Report to Warlord Gorchuk in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45786] = { id = 45786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feast of the Hounds" }
quests[45787] = { id = 45787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Scarab", description = "The Call of the Scarab event is occurring today. Speak with your faction's leader near the Gates of Ahn'Qiraj.", completion = "And who are you? {name}?\n\nAhh... yes, I believe I've heard mention of you before. Welcome to Silithus, {name}.\n\nToday, we celebrate the fabled war history of Kalimdor. Furthermore, we prove that the Alliance will always show the Horde their inferiority.\n\nAre you with me?", objectives = "Report to Field Marshal Snowfall in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45788] = { id = 45788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Speaker Awaits", description = "High Priest, we've received word from Netherlight Temple of a most curious visitor: Magni Bronzebeard, the very Speaker himself!\n\nWhat could he want from our order? You'd best head back to Netherlight, we'll hold down the front here.", completion = "Thank ye for coming so quickly, High {class}. King Magni, or I suppose I should say 'The Speaker,' thinks he's found a hidden Titan vault!", objectives = "Speak with Betild Deepanvil in Netherlight Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45789] = { id = 45789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sunken Vault", description = "'Ello, High Priest. The Speaker has just been telling us of a calling of sorts, coming from deep in the core of Azeroth.\n\nThe voice is telling 'im there's a lost Titan vault out there, near the Maelstrom. We dun know what's inside, but he's got tha feelin' it's got somethin' ta do with the Light, and you!\n\nBrann's got a vessel waitin' for ye, off the coast of Azsuna. Of course, I'll be accompanying ye as well, for cataloguing purposes. Can't go and let a chance like this go to waste!", progress = "Ta be one o' tha first to step foot in a lost Titan vault, it gives me tha chills!", completion = "Tis our greatest honor ta present ye with this steed, High {class}. An' thank ye for leading us, ye are truly blessed by the Light, an' so are all of us for havin' ye.", objectives = "Take Brann's vessel in Azsuna to the Sunken Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45790] = { id = 45790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Almai", objectives = "I will miss Brewmaster Blanche. She taught me to follow my dreams.\n\nAnd I have always wanted to study Mistweaving...\n\nGrandmaster {name}. If you will have me, I will defend you and our order from all that wish us harm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45791] = { id = 45791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Materiel" }
quests[45792] = { id = 45792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Occultist Onslaught" }
quests[45793] = { id = 45793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Occultist Onslaught" }
quests[45794] = { id = 45794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informing the Council", description = "I'll deal with this prisoner, but you should head back to Dreadscar Rift. \n\nLet the others know what we've discovered. We will need their help dealing with Kanrethad on the Broken Shore.", completion = "Thank you for bringing me news of Jubeka. It could not have come at a better time.\n\nWe've received information on Kanrethad's whereabouts.", objectives = "Return to Shinfel Blightsworn in Dreadscar Rift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45795] = { id = 45795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Presence of Power", description = "The demons appear to be harnessing an ancient power within the Temple itself. They've managed to twist and corrupt these sacred grounds with fel magic.\n\nWe must remove the demonic presence before we press our final advance.", progress = "Can you feel the immense energy?", completion = "Our fight doesn't end here, {name}.", objectives = "Repel the Legion threat from the Temple of a Thousand Lights, then Slay Portal-Keeper V'thaal and Zor'thaduun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45796] = { id = 45796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroying the Nest", description = "We have to put an end to Tugar's plot. These abominations must be destroyed, as well as their source!\n\nI think I know where. A group of neutral drogbar had a settlement nearby, but were pushed out by concerted demon and fel tauren attacks. That must be the place.\n\nGo there and stop their fel monster production at its source!", progress = "A tough fight to be sure, have you prevailed?", completion = "You have saved Thunder Totem and we owe you yet another debt.\n\nIt's a shame that Tugar wasn't there. As long as he lives, we are in danger.\n\nI will do everything I can to find him, and then we will finish this... together.", objectives = "Enter the Feltotem Caverns and ruin Tugar's plot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45797] = { id = 45797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playing with Green Fire" }
quests[45798] = { id = 45798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War'zuul the Provoker", description = "There'ss some obnoxious demon lord up there who's been yelling for hourss. \n\nWould you please shut him up already? I'm getting a terrible headache!", completion = "It'ss about time you shut that demon up. Thanksss...", objectives = "Kill War'zuul the Provoker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45799] = { id = 45799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shrouded Path Through Time", description = "The shrouded star flickers upon the land with its intermittent light ushering in an eerie mist upon the land. This star and the mists bring deep shadows to the land hiding its secrets and dangers. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", progress = "I foresee that you will follow the shrouded star, and walk the paths it reveals.", completion = "Ah, {name}, you have returned. An otherworldly air hangs heavy about you.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45801] = { id = 45801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avocation of Antonidas", description = "Archmage, I've found something you may be interested in. An old journal of the late Archmage, Antonidas. In it, he speaks of a project he was working on that I think we may be able to finish.\n\nIt was a sort of flying disc that could attune itself to the rider's magical attunement.\n\nBut I need your help tracking down the pieces. From what I could gather, he gave them to trusted friends and allies through the years. Perhaps you could persuade them to give us the pieces.", objectives = "Recover the three discs of Antonidas' unfinished project and return them to Kalec in your order hall. Speak to Archmage John Nicholas in Northrend, at the Purple Parlor about the Tri-Disc of the Arcane. Speak with Khadgar about the Tri-Disc of Fire. And speak with Archmage Cedric near the Dalaran Crater about the Tri-Disc of Frost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45802] = { id = 45802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avocation of Antonidas", description = "Archmage, I've found something you may be interested in. An old journal of the late Archmage, Antonidas. In it, he speaks of a project he was working on that I think we may be able to finish.\n\nIt was a sort of flying disc that could attune itself to the rider's magical attunement.\n\nBut I need your help tracking down the pieces. From what I could gather, he gave them to trusted friends and allies through the years. Perhaps you could persuade them to give us the pieces.", objectives = "Recover the three discs of Antonidas' unfinished project and return them to Kalec in your order hall. Speak to Archmage John Nicholas in Northrend, at the Purple Parlor about the Tri-Disc of the Arcane. Speak with Khadgar about the Tri-Disc of Fire. And speak with Archmage Cedric near the Dalaran Crater about the Tri-Disc of Frost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
